  ('ege_biology', 2027, 21, 1, 1, 'краткий', '1 балл — ответ полностью совпадает с эталоном и записан в форме из инструкции; иначе 0', null, null, null, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'atlas/ege_biology_2027.json#n=21'),
  ('ege_biology', 2027, 22, 2, 3, 'развёрнутый', 'Оценивается по полноте элементов ответа (3/2/1/0); за ошибки в дополнительной информации снимается 1 балл. РПК-2026: первый элемент засчитывается только при верном определении обеих переменных.', '{"kind":"ladder","steps":[{"points":3,"min":5},{"points":2,"min":4},{"points":1,"min":2}]}'::jsonb, null, 5, '[]'::jsonb, '[{"id":"D1","text":"за ошибки в дополнительной информации снимается 1 балл","points":1}]'::jsonb, '["РПК-2026: первый элемент засчитывается только при верном определении обеих переменных."]'::jsonb, 'atlas/ege_biology_2027.json#n=22'),
  ('ege_biology', 2027, 23, 2, 3, 'развёрнутый', 'Оценивается по полноте элементов ответа (3/2/1/0); за ошибки в дополнительной информации снимается 1 балл; проверка по рекомендациям к конкретному заданию (РПК-2026).', '{"kind":"ladder","steps":[{"points":3,"min":4},{"points":2,"min":3},{"points":1,"min":2}]}'::jsonb, null, 4, '[]'::jsonb, '[{"id":"D1","text":"за ошибки в дополнительной информации снимается 1 балл","points":1}]'::jsonb, '["второй элемент засчитывается только при наличии всех расчётов"]'::jsonb, 'atlas/ege_biology_2027.json#n=23'),
  ('ege_biology', 2027, 24, 2, 3, 'развёрнутый', 'Оценивается по полноте элементов, первый элемент (узнавание объекта) обязателен для 2–3 баллов; РПК-2026: если объект не определён, но объяснение полное и верное — 1 балл.', '{"kind":"ladder","steps":[{"points":3,"min":6,"require":["E1"]},{"points":2,"min":4,"require":["E1"]},{"points":1,"min":3,"require":["E1"]},{"points":1,"min":5}]}'::jsonb, null, 7, '[]'::jsonb, '[]'::jsonb, '["второй вариант задания (археоптерикс, PDF-стр. 15–16) имеет свою шкалу из 5 элементов"]'::jsonb, 'atlas/ege_biology_2027.json#n=24'),
  ('ege_biology', 2027, 25, 2, 3, 'развёрнутый', 'Оценивается по полноте элементов ответа (3/2/1/0); за ошибки в дополнительной информации снимается 1 балл.', '{"kind":"ladder","steps":[{"points":3,"min":5},{"points":2,"min":3},{"points":1,"min":2}]}'::jsonb, null, 6, '[]'::jsonb, '[{"id":"D1","text":"за ошибки в дополнительной информации снимается 1 балл","points":1}]'::jsonb, '[]'::jsonb, 'atlas/ege_biology_2027.json#n=25'),
  ('ege_biology', 2027, 26, 2, 4, 'развёрнутый', 'Оценивается по полноте элементов ответа (4/3/2/1/0), для 4 баллов обязателен расчётный элемент 7; за ошибки в дополнительной информации снимается 1 балл.', '{"kind":"ladder","steps":[{"points":4,"min":6,"require":["E7"]},{"points":3,"min":4},{"points":2,"min":3},{"points":1,"min":2}]}'::jsonb, null, 7, '[]'::jsonb, '[{"id":"D1","text":"за ошибки в дополнительной информации снимается 1 балл","points":1}]'::jsonb, '[]'::jsonb, 'atlas/ege_biology_2027.json#n=26'),
  ('ege_biology', 2027, 27, 2, 3, 'развёрнутый', 'Закрытый ряд: оценивается схема решения (3/2/1/0). РПК-2026: элементы с нуклеиновыми кислотами при перепутанных концах 5ʹ/3ʹ не засчитываются; без требуемого пояснения высший балл не ставится.', null, null, null, '[]'::jsonb, '[]'::jsonb, '["у остальных четырёх вариантов задания 27 в демоверсии (PDF-стр. 19–21) свои шкалы, тоже на 3 балла"]'::jsonb, 'atlas/ege_biology_2027.json#n=27'),
  ('ege_biology', 2027, 28, 2, 3, 'развёрнутый', 'Закрытый ряд: оценивается схема решения (3/2/1/0); схема скрещивания обязательна; допускается иная генетическая символика.', '{"kind":"ladder","steps":[{"points":3,"min":3},{"points":2,"min":2},{"points":1,"min":1}]}'::jsonb, null, 3, '[]'::jsonb, '[]'::jsonb, '["элементы 1 и 2 засчитываются только при наличии генотипов, фенотипов и пола всех потомков"]'::jsonb, 'atlas/ege_biology_2027.json#n=28'),
