  ('ege_chemistry', 2027, 29, 2, 2, 'развёрнутый', 'Поэлементная проверка: по 1 баллу за каждый элемент ответа, максимум 2. Если молекулярное уравнение не соответствует условию или продукты определены неверно, электронный баланс не оценивается (0 баллов).', '{"kind":"sum"}'::jsonb, '[{"id":"E1","text":"Выбраны вещества (окислитель и восстановитель из перечня) и записано уравнение ОВР, соответствующее условию"},{"id":"E2","text":"Составлен электронный баланс, указаны окислитель и восстановитель"}]'::jsonb, 2, '[{"unless":"E1","void":["E2"],"from":"Если молекулярное уравнение не соответствует условию или продукты определены неверно, электронный баланс не оценивается (0 баллов)."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'atlas/ege_chemistry_2027.json#n=29'),
  ('ege_chemistry', 2027, 30, 2, 2, 'развёрнутый', 'Поэлементная проверка: по 1 баллу за каждый элемент ответа, максимум 2.', '{"kind":"sum"}'::jsonb, '[{"id":"E1","text":"Выбраны вещества и записано молекулярное уравнение реакции ионного обмена, отвечающей условию"},{"id":"E2","text":"Записаны полное и сокращённое ионные уравнения реакции"}]'::jsonb, 2, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'atlas/ege_chemistry_2027.json#n=30'),
