  ('oge_chemistry', 2027, 20, 2, 3, 'развёрнутый', 'по 1 баллу за каждый верный элемент ответа: 3 — все три элемента, 2 — два, 1 — один, 0 — все неверны или отсутствуют', '{"kind":"sum"}'::jsonb, '[{"id":"E1","text":"электронный баланс (процессы окисления и восстановления)"},{"id":"E2","text":"указаны окислитель и восстановитель"},{"id":"E3","text":"молекулярное уравнение с коэффициентами по балансу"}]'::jsonb, 3, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'atlas/oge_chemistry_2027.json#n=20'),
  ('oge_chemistry', 2027, 21, 2, 3, 'развёрнутый', 'по 1 баллу за каждое верное молекулярное уравнение из трёх по схеме превращений: 3 — все три, 2 — два, 1 — одно, 0 — все неверны или отсутствуют', '{"kind":"sum"}'::jsonb, '[{"id":"E1","label":"уравнение 1","text":"верное молекулярное уравнение из трёх по схеме превращений"},{"id":"E2","label":"уравнение 2","text":"верное молекулярное уравнение из трёх по схеме превращений"},{"id":"E3","label":"уравнение 3","text":"верное молекулярное уравнение из трёх по схеме превращений"}]'::jsonb, 3, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'atlas/oge_chemistry_2027.json#n=21'),
  ('oge_chemistry', 2027, 22, 2, 3, 'развёрнутый', 'по 1 баллу за каждый верный элемент ответа: 3 — все три элемента, 2 — два, 1 — один, 0 — все неверны или отсутствуют; ошибка в коэффициентах, приведшая к ошибке в расчётах, снижает оценку на 1 балл', '{"kind":"sum"}'::jsonb, '[{"id":"E1","text":"Верно записано уравнение реакции по условию"},{"id":"E2","text":"верно выполнены вычисления с величинами из условия"},{"id":"E3","text":"показана логически обоснованная взаимосвязь величин, по которой найдена искомая величина"}]'::jsonb, 3, '[]'::jsonb, '[]'::jsonb, '["ошибка в коэффициентах, приведшая к ошибке в расчётах, снижает оценку на 1 балл"]'::jsonb, 'atlas/oge_chemistry_2027.json#n=22'),
  ('oge_chemistry', 2027, 23, 2, 5, 'практический', 'К1 (0–2) — уравнения реакций + К2 (0–3) — оформление результатов эксперимента; каждый верный элемент — 1 балл; максимум 5', '{"kind":"groups","groups":[{"label":"К1","ids":["E1","E2"],"steps":[{"points":2,"min":2},{"points":1,"min":1}]},{"label":"К2","ids":["E3","E4","E5"],"steps":[{"points":3,"min":3},{"points":2,"min":2},{"points":1,"min":1}]}]}'::jsonb, '[{"id":"E1","label":"К1, опыт 1","text":"верно составлены молекулярное, полное и сокращённое ионные уравнения реакций"},{"id":"E2","label":"К1, опыт 2","text":"верно составлены молекулярное, полное и сокращённое ионные уравнения реакций"},{"id":"E3","label":"К2, опыт 1","text":"в таблице верно заполнены строки опыта 1 и опыта 2 (реактив, наблюдаемые признаки с веществами из обеих склянок)"},{"id":"E4","label":"К2, опыт 2","text":"в таблице верно заполнены строки опыта 1 и опыта 2 (реактив, наблюдаемые признаки с веществами из обеих склянок)"},{"id":"E5","label":"К2, вывод","text":"верно сделан вывод о веществах в склянках № 1 и № 2"}]'::jsonb, 5, '[]'::jsonb, '[]'::jsonb, '["К2: правильно заполнены только две любые строки таблицы ИЛИ верные результаты и вывод, но не в табличной форме"]'::jsonb, 'atlas/oge_chemistry_2027.json#n=23')
